	if _, err := Verses(0, 0); err != nil {
		t.Fatalf("Verses(0,0) error: %v", err)
	}
	if _, err := Verses(5, 6); err == nil {
		t.Fatal("Verses(5,6) expected error")
	}
	if _, err := Verses(100, 0); err == nil {
		t.Fatal("Verses(100,0) expected error")
	}
}
